'use strict';
const fs=require('fs'),path=require('path'),zlib=require('zlib'),crypto=require('crypto');
const files=JSON.parse(zlib.inflateSync(Buffer.from('','base64')));
for(const f of files){if(!/^(SOFIA_APP|src|public|tests|tools|docs)\//.test(f.path)||f.path.split('/').includes('..'))throw Error('Unsafe path');if(crypto.createHash('sha256').update(f.content).digest('hex')!==f.sha256)throw Error('Content mismatch');fs.mkdirSync(path.dirname(f.path),{recursive:true});fs.writeFileSync(f.path,f.content);}
const p='SOFIA_APP/package-lock.json',lock=JSON.parse(fs.readFileSync(p));if(!['0.3.25','0.3.26'].includes(lock.version))throw Error('Wrong baseline');lock.version=lock.packages[''].version='0.3.26';fs.writeFileSync(p,JSON.stringify(lock,null,2)+'\n');console.log('Applied',files.length,'verified files');
